Dst_Trans_Resp dst_cmd_lock(UInt8 page)
{

  UInt8 dummy = 0;

  TRACE("\r\nDST_CMD_LOCK\r\n");
   
  dst_set_lock(page) ;//bitfield_wr(dst_vars.key_mem->lock_status , page , page , DST_PAGE_STATUS_LOCK) ;

 #if DBG_DST == 1
   dst_dbg_print("\nDst Lock Page ", &page, 1);
 #endif 
 
  return(dst_cmd_gen_read(page , &dummy , dummy )) ;
}
